Looking at the implementation, I need to write comprehensive tests covering:

1. **Authorization decisions**: ALLOW/DENY/default deny, deny-override behavior (the ticket bug)
2. **Principal matching**: wildcard, user:X, role:X (exact matching, no glob patterns)
3. **Pattern matching**: trailing `*` as prefix, non-final `*` as literal, case sensitivity
4. **Validation**: required fields, effect values, validation before decision
5. **Edge cases**: multiple roles, extra fields ignored

Here's my pytest suite:

```json
{"code": "import impl
import pytest


def test_allow_policy_grants_access():
    """Matching ALLOW policy grants access."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:Get", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_deny_policy_denies_access():
    """Matching DENY policy denies access."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    policies = [{"effect": "DENY", "principal": "user:alice", "action": "s3:Get", "resource": "file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_no_matching_policies_default_deny():
    """No matching policies or empty list defaults to DENY."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    assert impl.authorize(request, []) == "DENY"

    policies = [{"effect": "ALLOW", "principal": "user:bob", "action": "s3:Get", "resource": "file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_deny_overrides_allow_ticket_bug():
    """DENY overrides ALLOW: role DENY beats user ALLOW (the ticket bug)."""
    request = {"subject": "alice", "roles": ["contractor"], "action": "docs:Read", "resource": "docs/reports/q1"}
    policies = [
        {"effect": "ALLOW", "principal": "user:alice", "action": "docs:Read", "resource": "docs/reports/*"},
        {"effect": "DENY", "principal": "role:contractor", "action": "docs:Read", "resource": "docs/reports/*"}
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_deny_overrides_allow_reverse_order():
    """DENY overrides ALLOW even when DENY comes after."""
    request = {"subject": "alice", "roles": ["contractor"], "action": "docs:Read", "resource": "docs/reports/q1"}
    policies = [
        {"effect": "DENY", "principal": "role:contractor", "action": "docs:Read", "resource": "docs/reports/*"},
        {"effect": "ALLOW", "principal": "user:alice", "action": "docs:Read", "resource": "docs/reports/*"}
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_principal_wildcard():
    """Wildcard principal '*' matches any request."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:Get", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_user_exact():
    """user:X principal matches when subject is exactly X."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:Get", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"

    request2 = {"subject": "bob", "roles": [], "action": "s3:Get", "resource": "file"}
    assert impl.authorize(request2, policies) == "DENY"


def test_principal_user_no_glob():
    """user:al* is literal principal, not glob pattern."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "user:al*", "action": "s3:Get", "resource": "file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_principal_role_matches():
    """role:X principal matches if X is in request roles list."""
    request = {"subject": "alice", "roles": ["viewer", "admin"], "action": "s3:Get", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "role:admin", "action": "s3:Get", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"

    request2 = {"subject": "alice", "roles": ["viewer"], "action": "s3:Get", "resource": "file"}
    assert impl.authorize(request2, policies) == "DENY"


def test_action_prefix_match():
    """Action pattern s3:Get* matches s3:GetObject and s3:Get."""
    request1 = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "file"}
    request2 = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:Get*", "resource": "file"}]

    assert impl.authorize(request1, policies) == "ALLOW"
    assert impl.authorize(request2, policies) == "ALLOW"

    request3 = {"subject": "alice", "roles": [], "action": "s3:PutObject", "resource": "file"}
    assert impl.authorize(request3, policies) == "DENY"


def test_resource_prefix_match():
    """Resource pattern docs/reports/* matches docs/reports/q1 but not docs/reportsQ1."""
    request1 = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "docs/reports/q1"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:Get", "resource": "docs/reports/*"}]
    assert impl.authorize(request1, policies) == "ALLOW"

    request2 = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "docs/reportsQ1"}
    assert impl.authorize(request2, policies) == "DENY"


def test_nonfinal_star_is_literal():
    """Non-final * is literal asterisk, not wildcard."""
    request = {"subject": "alice", "roles": [], "action": "s3:*Object", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:*Object", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"

    request2 = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "file"}
    assert impl.authorize(request2, policies) == "DENY"


def test_case_sensitive_matching():
    """All matching is case-sensitive."""
    request = {"subject": "Alice", "roles": [], "action": "S3:GET", "resource": "FILE"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:get", "resource": "file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_request_validation_missing_fields():
    """ValueError raised for missing required request fields."""
    request_no_subject = {"roles": [], "action": "s3:Get", "resource": "file"}
    with pytest.raises(ValueError):
        impl.authorize(request_no_subject, [])

    request_roles_not_list = {"subject": "alice", "roles": "admin", "action": "s3:Get", "resource": "file"}
    with pytest.raises(ValueError):
        impl.authorize(request_roles_not_list, [])


def test_policy_validation_missing_fields():
    """ValueError raised for missing required policy fields."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}

    policy_no_effect = [{"principal": "*", "action": "s3:Get", "resource": "file"}]
    with pytest.raises(ValueError):
        impl.authorize(request, policy_no_effect)


def test_policy_validation_invalid_effect():
    """ValueError raised for invalid effect; error message includes verbatim value."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}

    with pytest.raises(ValueError, match="Allow"):
        impl.authorize(request, [{"effect": "Allow", "principal": "*", "action": "s3:Get", "resource": "file"}])

    with pytest.raises(ValueError, match="PERMIT"):
        impl.authorize(request, [{"effect": "PERMIT", "principal": "*", "action": "s3:Get", "resource": "file"}])


def test_validation_before_decision():
    """All policies validated before decision logic executes."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file"}
    policies = [
        {"effect": "ALLOW", "principal": "*", "action": "s3:Get", "resource": "file"},
        {"effect": "INVALID", "principal": "*", "action": "s3:Get", "resource": "file"}
    ]
    with pytest.raises(ValueError, match="INVALID"):
        impl.authorize(request, policies)


def test_extra_fields_ignored():
    """Extra fields in request and policies are ignored."""
    request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "file", "extra": "value"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "s3:Get", "resource": "file", "extra": "x"}]
    assert impl.authorize(request, policies) == "ALLOW"
"}
